import { createRequire } from 'module'; const { chromium } = createRequire(import.meta.url)('playwright');
const dir = process.argv[2];
const msgIcon = `<svg viewBox="0 0 60 60" width="84" height="84"><rect width="60" height="60" rx="14" fill="#34c759"/><path d="M30 15c-9.4 0-17 6-17 13.5 0 4.3 2.5 8.1 6.4 10.6-.3 2.4-1.5 4.6-3.4 6.3 3.6-.2 6.8-1.6 9-3.6 1.6.4 3.3.7 5 .7 9.4 0 17-6 17-13.5S39.4 15 30 15z" fill="#fff"/></svg>`;
const N = {
  nHook:{app:'پیام‌ها', icon:msgIcon, t:'مریم، مشتری فردا', b:'ببخشید عزیزم، فردا نمی‌تونم بیام'},
  nPay:{app:'فرفرو', icon:`<img src="data:image/png;base64," width="84" height="84" style="border-radius:20px">`, t:'درخواست نوبت تازه', b:'فردا ساعت ۹:۳۰ · از استوری‌ت'},
};
const caps = {
  hook:{html:'نوبت فردا <em>کنسل</em> شد.'},
  chair:{html:'یه صندلی خالی.<br><em>یه روز ضرر.</em>'},
  pay:{html:'یه مشتری تازه،<br><em>از همون استوری.</em>'},
};
const font=`@font-face{font-family:V;src:url(file://${dir}/vazirmatn-arabic-wght-normal.woff2)}@font-face{font-family:V;src:url(file://${dir}/vazirmatn-latin-wght-normal.woff2)}html,body{margin:0;background:transparent;width:1080px;height:1920px}`;
const b = await chromium.launch(); const p = await b.newPage({viewport:{width:1080,height:1920}});
for (const [k,n] of Object.entries(N)) {
  await p.setContent(`<style>${font}.n{position:absolute;left:36px;right:36px;top:760px;height:250px;box-sizing:border-box;background:#f6f4f7;border-radius:44px;
  box-shadow:0 10px 40px rgba(0,0,0,.25);display:flex;align-items:center;gap:30px;padding:0 40px;direction:rtl;font-family:V}
  .x{flex:1;min-width:0}.h{display:flex;justify-content:space-between;color:#7a7480;font-size:30px;font-weight:500}
  .t{font-size:42px;font-weight:800;color:#111;margin-top:4px}.bd{font-size:36px;color:#222;margin-top:2px}</style>
  <div class="n">${n.icon}<div class="x"><div class="h"><span>${n.app}</span><span>الان</span></div><div class="t">${n.t}</div><div class="bd">${n.b}</div></div></div>`,{waitUntil:'load'});
  await p.evaluate(()=>document.fonts.ready); await p.screenshot({path:`${dir}/${k}.png`,omitBackground:true});
}
for (const [k,c] of Object.entries(caps)) {
  await p.setContent(`<style>${font}.b{position:absolute;left:50%;top:1290px;transform:translate(-50%,-50%);direction:rtl;text-align:center;font-family:V;font-weight:800;font-size:74px;line-height:1.45;color:#fff;white-space:nowrap;background:rgba(28,20,36,.82);border-radius:30px;padding:26px 54px}em{font-style:normal;color:#ff7db8}</style><div class="b">${c.html}</div>`,{waitUntil:'load'});
  await p.evaluate(()=>document.fonts.ready); await p.screenshot({path:`${dir}/${k}.png`,omitBackground:true});
}
await b.close();
